<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3'
import { ref } from 'vue'
const props=defineProps<{result:{users?:any[];total?:number;next_token?:string|null};filters:Record<string,any>;error:string|null}>()
const search=ref(props.filters.search_term||''),status=ref(props.filters.deactivated||'all'),order=ref(props.filters.order_by||'name'),loading=ref(false),createOpen=ref(false)
const create=useForm({user_id:'',password:'',displayname:'',admin:false,deactivated:false,locked:false})
const apply=()=>{loading.value=true;router.get('/users',{search_term:search.value,from:0,limit:50,order_by:order.value,deactivated:status.value==='all'?undefined:status.value},{preserveState:true,onFinish:()=>loading.value=false})}
const page=(from:string|number)=>router.get('/users',{...props.filters,from,limit:50},{preserveState:true})
const statusLabel=(u:any)=>u.deactivated?'غیرفعال':u.locked?'قفل‌شده':u.shadow_banned?'Shadow ban':'فعال'
</script>
<template><Head title="مدیریت کاربران"/><v-container fluid class="pa-6"><div class="d-flex align-center justify-space-between mb-5"><div><h1 class="text-h4">کاربران</h1><div class="text-medium-emphasis">مدیریت حساب‌های Matrix</div></div><v-btn color="primary" prepend-icon="mdi-account-plus" @click="createOpen=true">ایجاد کاربر</v-btn></div><v-card rounded="xl" class="pa-4"><v-row align="center"><v-col cols="12" md="4"><v-text-field v-model="search" label="جستجو بر اساس شناسه یا نام" prepend-inner-icon="mdi-magnify" hide-details @keyup.enter="apply"/></v-col><v-col cols="6" md="3"><v-select v-model="status" label="وضعیت" :items="[{title:'همه',value:'all'},{title:'فعال',value:'false'},{title:'غیرفعال',value:'true'}]" hide-details/></v-col><v-col cols="6" md="3"><v-select v-model="order" label="مرتب‌سازی" :items="[{title:'شناسه',value:'name'},{title:'آخرین فعالیت',value:'last_seen_ts'},{title:'نام نمایشی',value:'displayname'}]" hide-details/></v-col><v-col cols="12" md="2"><v-btn block color="primary" @click="apply">جستجو</v-btn></v-col></v-row><v-alert v-if="error" type="error" variant="tonal" class="my-4">{{ error }}</v-alert><v-skeleton-loader v-if="loading" type="table-row@8"/><v-table v-else class="mt-4"><thead><tr><th>شناسه</th><th>نام نمایشی</th><th>وضعیت</th><th>مدیر</th><th>آخرین فعالیت</th><th></th></tr></thead><tbody><TransitionGroup name="row"><tr v-for="u in (result.users||[])" :key="u.name"><td class="font-weight-medium">{{ u.name }}</td><td>{{ u.displayname||'—' }}</td><td><v-chip size="small" :color="u.deactivated?'error':u.locked?'warning':'success'">{{ statusLabel(u) }}</v-chip></td><td>{{ u.admin?'بله':'خیر' }}</td><td>{{ u.last_seen_ts?new Date(u.last_seen_ts).toLocaleString():'—' }}</td><td><v-btn size="small" variant="tonal" :href="'/users/'+encodeURIComponent(u.name)">جزئیات</v-btn></td></tr></TransitionGroup><tr v-if="!(result.users||[]).length"><td colspan="6" class="text-center pa-8">کاربری یافت نشد.</td></tr></tbody></v-table><div class="d-flex align-center justify-space-between mt-3"><span class="text-caption">تعداد کل: {{ result.total??0 }}</span><div class="d-flex ga-2"><v-btn variant="tonal" :disabled="Number(filters.from||0)<=0" @click="page(Math.max(0,Number(filters.from||0)-50))">قبلی</v-btn><v-btn variant="tonal" :disabled="!result.next_token" @click="page(result.next_token||0)">بعدی</v-btn></div></div></v-card><v-dialog v-model="createOpen" max-width="600"><v-card rounded="xl"><v-card-title>ایجاد حساب Matrix</v-card-title><v-card-text><v-form @submit.prevent="create.post('/users',{onSuccess:()=>createOpen=false})"><v-text-field v-model="create.user_id" label="شناسه کامل، مانند @user:example.org"/><v-text-field v-model="create.password" label="گذرواژه اولیه" type="password"/><v-text-field v-model="create.displayname" label="نام نمایشی"/><v-switch v-model="create.admin" label="مدیر سرور"/><v-switch v-model="create.locked" label="قفل‌شده"/><v-btn type="submit" color="primary" block :loading="create.processing" :disabled="create.password.length<12||!create.user_id.startsWith('@')">ایجاد کاربر</v-btn></v-form></v-card-text><v-card-actions><v-spacer/><v-btn variant="text" @click="createOpen=false">بستن</v-btn></v-card-actions></v-card></v-dialog></v-container></template>
<style scoped>.row-enter-active,.row-leave-active{transition:all .25s ease}.row-enter-from{opacity:0;transform:translateY(8px)}@media(prefers-reduced-motion:reduce){.row-enter-active,.row-leave-active{transition:none}}</style>
